/** Exact unchanged frozen full12 consumer; fixture only, never starts a process. */
import assert from'node:assert/strict'
export function makeFixtureAudit({pinsFile,readOwn}){
async function auditOwnedRetired(pins,directory,ms=2000,onResult){const proof=await pinsFile(pins,directory),result=await readOwn(['-Operation','retired','-PinsFile',proof.file,'-PinsSHA256',proof.sha256],ms);assert.equal(result.timebase,'DateTimeUtcTicks');assert(Array.isArray(result.rows)&&result.rows.length===pins.length);assert.equal(typeof result.passed,'boolean');assert.deepEqual(Object.keys(result).sort(),['passed','rows','timebase']);const reasons=new Set(['process-absent','same-handle-signaled','same-handle-signaled-after-query','same-handle-signaled-after-identity','different-birth-reuse','exact-original-alive']);for(let i=0;i<pins.length;i++){const row=result.rows[i],pin=pins[i];assert.deepEqual(Object.keys(row).sort(),['birthTicks','pid','reason','retired']);assert.equal(row.pid,pin.pid);assert.equal(row.birthTicks,pin.birthTicks);assert.equal(typeof row.retired,'boolean');assert(reasons.has(row.reason))}assert.equal(result.passed,result.rows.every(row=>row.retired));if(onResult!==undefined){assert.equal(typeof onResult,'function');await onResult(structuredClone(result))}assert.equal(result.passed,true,'Exact own Windows process pin remains alive or unknown');return result}
return auditOwnedRetired
}
